'use client';

import {createContext, useContext} from 'react';

export const FieldSetDisabledContext = createContext(false);

/** An individual control cannot re-enable itself inside a disabled fieldset. */
export function useFieldDisabled(disabled?: boolean) {
  return useContext(FieldSetDisabledContext) || disabled;
}

'use client';

import { Switch as AriaSwitch, type SwitchProps as AriaSwitchProps } from 'react-aria-components';
import { cx } from '@/utils/cx';
import { useFieldDisabled } from '@/components/base/field/field-context';

export type SwitchCardProps = AriaSwitchProps & { title: string; description: string; className?: string };
export function SwitchCard({ title, description, className, ...props }: SwitchCardProps) {
  const isDisabled = useFieldDisabled(props.isDisabled);
  return <AriaSwitch {...props} isDisabled={isDisabled} className={cx('ui-switch-card', className)}><span className="ui-switch-card__copy"><strong>{title}</strong><small>{description}</small></span><span className="ui-switch__track" aria-hidden="true"><span className="ui-switch__thumb" /></span></AriaSwitch>;
}

'use client';

import type { ReactNode } from 'react';
import { Switch as AriaSwitch, type SwitchProps as AriaSwitchProps } from 'react-aria-components';
import { cx } from '@/utils/cx';
import { useFieldDisabled } from '@/components/base/field/field-context';

export type SwitchProps = AriaSwitchProps & { children?: ReactNode; size?: 'sm' | 'md' | 'lg'; shape?: 'pill' | 'rectangle'; className?: string };
export function Switch({ children, size = 'md', shape = 'pill', className, ...props }: SwitchProps) {
  const isDisabled = useFieldDisabled(props.isDisabled);
  return <AriaSwitch {...props} isDisabled={isDisabled} data-size={size} data-shape={shape} className={cx('ui-switch', className)}><span className="ui-switch__track" aria-hidden="true"><span className="ui-switch__thumb" /></span>{children && <span className="ui-switch__label">{children}</span>}</AriaSwitch>;
}

import { extendTailwindMerge } from 'tailwind-merge';

const typeFamilies = [
  'large-title', 'display-1', 'display-2', 'display-3', 'display-4',
  'title-1', 'title-2', 'title-3', 'headline', 'body', 'body-2',
  'caption-1', 'caption-2',
] as const;
const weights = ['regular', 'medium', 'semibold', 'bold'] as const;

// Custom text styles share Tailwind's text-* namespace with colors.
// Registering them keeps both classes when they appear together.
export const cx = extendTailwindMerge({
  extend: {
    classGroups: {
      'font-size': [{ text: typeFamilies.flatMap((family) => weights.map((weight) => `${family}-${weight}`)) }],
    },
  },
});
